    for (const l of (j && j.list) || []) { if (!l || !/^[0-9a-f]{6}$/.test(l.hex || '')) continue; mon.push(l); hexes.add(l.hex); if (l.reg && !store.getHex(l.hex)) store.mergeHex(l.hex, { reg: l.reg, type: l.type, ladd: !!l.ladd || undefined }); }
